def transform(g):
    a=[r[:] for r in g]
    # Zero cells are occlusions over two tiled regions. Determine the tile's
    # repeating row/column sequence from nearby nonzero pixels by majority vote.
    from collections import Counter
    h,w=len(a),len(a[0])
    for r in range(h):
        for c in range(w):
            if a[r][c]!=0: continue
            votes=[]
            for rr,cc,weight in [(r,c-1,2),(r,c+1,2),(r-1,c,2),(r+1,c,2),(r,c-5,1),(r,c+5,1),(r-5,c,1),(r+5,c,1)]:
                if 0<=rr<h and 0<=cc<w and a[rr][cc]!=0 and a[rr][cc] not in (4,):
                    votes += [a[rr][cc]]*weight
            # For numeric texture, row runs cycle with period 5; find neighboring
            # exemplar at matching phase (offsets preserve color cycle).
            for d in (-10,-5,5,10):
                if 0<=c+d<w and a[r][c+d] not in (0,4): votes += [a[r][c+d]]*3
                if 0<=r+d<h and a[r+d][c] not in (0,4): votes += [a[r+d][c]]*3
            if votes: a[r][c]=Counter(votes).most_common(1)[0][0]
    # Fill remaining zero borders according to frame regions
    for r in range(h):
        for c in range(w):
            if a[r][c]==0:
                a[r][c]=4 if r==2 or (r>=2 and c==2) else 1
    return a
