def transform(g):
    """Restore zero occlusions in the periodic ARC color field and its frame."""
    a=[row[:] for row in g]
    h,w=len(a),len(a[0])
    palette=[1,3,5,7,9]
    for r in range(h):
        for c in range(w):
            if a[r][c]!=0:
                continue
            if r<2:
                a[r][c]=1
            elif r==2 or c==2:
                a[r][c]=4
            elif c<2:
                a[r][c]=1
            else:
                # Continue the five-color cycle from the nearest visible cell in this row.
                known=[k for k in range(w) if a[r][k] in palette]
                if known:
                    k=min(known,key=lambda x:abs(x-c))
                    a[r][c]=palette[(palette.index(a[r][k])+c-k)%5]
                else:
                    a[r][c]=palette[(r+c)%5]
    return a
